header='''<header class="toolbar"><div class="app-brand"><span class="brand-mark">◇</span><span class="brand-label"><strong>XP Canvas</strong><small>PYTHON UML</small></span></div><div class="toolbar-separator"></div><nav class="altitude-toolbar"><button>Architecture</button><button>Packages</button><button>Modules</button><button class="active">Code</button></nav><div class="toolbar-separator"></div><label class="select-field focus-select">◎ <select><option>agent.py</option></select></label><label class="search-field">⌕ <input placeholder="Find a symbol"/></label><div class="toolbar-spacer"></div><div class="canvas-lens-switch"><button class="{map_active}">⌘ UML</button><button class="{flow_active}">≋ Flow</button></div><div class="toolbar-action-group"><button class="icon-button">▦</button><button class="icon-button">▣</button><button class="icon-button">⑂</button><button class="icon-button">⚙</button></div></header><div class="filterbar"><span class="section-eyebrow">◌ CONNECTIONS</span><span class="active-filter-summary">4 types visible</span><span class="filter-divider"></span><label class="inline-select"><span>Trace</span><select><option>All relationships</option></select></label><div class="toolbar-spacer"></div><span class="git-section-label">⊙ GIT DIFF</span><input class="baseline-input" value="HEAD~1" readonly/><button class="button-compare">⇄ Compare</button></div>'''
def block(name, role, kind,links=1):
    glyph={'class':'▣','callable':'ƒ','data':'#','module':'▤'}[role]
    return f'<div class="structure-block role-{role}" style="--part-weight:2;flex:1 1 120px"><span class="structure-glyph">{glyph}</span><span class="structure-name">{html.escape(name)}</span><span class="structure-metric">{links} links</span></div>'
def card(name,role,kind,file,x,y,width,children=(),status='',source=''):
    icon={'class':'▣','callable':'ƒ','module':'▤','data':'#'}[role]
    bits=''.join(block(*c) for c in children)
    content=f'<div class="uml-heading"><span class="uml-kind-icon">{icon}</span><div class="uml-identity"><span class="uml-eyebrow">«{kind}»</span><strong class="uml-title">{html.escape(name)}</strong></div><span class="mock-text">⌄　⋮　⇥</span></div>'
    if status:content+=f'<div class="node-status-line"><span class="status-dot"></span>{status}</div>'
    if bits:content+=f'<section class="structure-map structure-blocks"><div class="structure-caption"><span>▦ STRUCTURE</span><span>{len(children)} constructs · 7 links</span></div><div class="structure-blocks">{bits}</div></section>'
    if role=='class':content+='<section class="field-strip"><div class="field-caption"># FIELDS <span>2 indexed</span></div><div class="field-tokens"><span class="field-token">_context</span><span class="field-token">tools</span></div></section>'
    if source:content+=f'<div class="uml-source"><div class="source-heading"><span class="source-heading-file">{file}</span><span class="read-only-label">PREVIEW</span></div><pre class="source-preview" style="min-height:0;max-height:132px">{source}</pre></div>'
    content+=f'<footer class="uml-footer"><span>▤ &nbsp;{file}</span><span>L8</span></footer>'
    cls=(' uml-class' if role=='class' else ' uml-module' if role=='module' else '')+(' selected change-modified' if status else '')
    if children:cls+=' uml-anatomy'
    return f'<div class="demo-node uml-node role-{role}{cls}" style="left:{x}px;top:{y}px;width:{width}px">{content}</div>'
