flow='''<main class="graph-region"><section class="sankey-lens" style="position:relative;inset:auto;min-height:800px"><header class="sankey-topbar"><div class="sankey-heading"><span class="sankey-kicker">◈ RELATIONSHIP FLOW</span><h2>Agent.execute</h2><p>Ribbons show <strong>static source relationships</strong>, not runtime frequency, data volume or performance.</p></div><div class="sankey-actions"><label>Relationship<select><option>Calls</option></select></label><button class="button-primary">⌘ UML map</button></div></header><div class="flow-metrics"><div><strong>23</strong><span>Incoming · 22% of workspace relationships</span></div><div><strong>17</strong><span>Outgoing · 16% of workspace relationships</span></div><div><strong>105</strong><span>Static callsites in this graph view</span></div></div><div class="sankey-diagram-wrap"><svg class="sankey-diagram" viewBox="0 0 1100 590" role="img"><defs><linearGradient id="flow-in" x1="0" x2="1"><stop offset="0%" stop-color="#579df4" stop-opacity=".3"/><stop offset="100%" stop-color="#579df4" stop-opacity=".8"/></linearGradient><linearGradient id="flow-out" x1="0" x2="1"><stop offset="0%" stop-color="#66c7a4" stop-opacity=".8"/><stop offset="100%" stop-color="#66c7a4" stop-opacity=".28"/></linearGradient></defs><text x="76" y="56" class="sankey-column-label">CALLERS / USERS</text><text x="484" y="56" class="sankey-column-label">FOCUSED CONSTRUCT</text><text x="864" y="56" class="sankey-column-label">DEPENDENCIES / USES</text><line x1="350" y1="75" x2="350" y2="537" class="sankey-divider"/><line x1="766" y1="75" x2="766" y2="537" class="sankey-divider"/>'''
# numeric geometry approximating ribbon proportions for illustration
ribbons=[('in',250,196,63,'handle_request',7,76,158),('in',250,273,109,'plan',12,76,252),('in',250,356,67,'pipeline',4,76,354),('out',629,224,64,'ToolRegistry.run',6,864,180),('out',629,312,76,'search_tools',7,864,289),('out',629,408,43,'write_log',4,864,406)]
for direction,x0,y0,thick,name,n,x1,y1 in ribbons:
    xstart,xend=(250,484) if direction=='in' else (629,864)
    c=(xend-xstart)*.45;h=thick/2
    d=f'M{xstart},{y0-h} C{xstart+c},{y0-h} {xend-c},{y1-h} {xend},{y1-h} L{xend},{y1+h} C{xend-c},{y1+h} {xstart+c},{y0+h} {xstart},{y0+h} Z'
    flow+=f'<path class="flow-ribbon {"incoming" if direction=="in" else "outgoing"}" fill="url(#flow-{direction})" d="{d}"/>'
flow+='<rect x="484" y="155" width="145" height="303" rx="12" class="sankey-center"/><text x="557" y="292" text-anchor="middle" class="sankey-center-name">execute</text><text x="557" y="317" text-anchor="middle" class="sankey-center-kind">METHOD</text>'
for direction,x0,y0,thick,name,n,x1,y1 in ribbons:
    h=max(35,thick); y=y1-h/2;x=x1
    flow+=f'<g class="sankey-peer"><rect x="{x}" y="{y}" width="174" height="{h}" rx="7" class="sankey-bar role-callable"/><text x="{x+12}" y="{y+h/2+4}" class="sankey-bar-text">{name}</text><text x="{x+164}" y="{y+h/2+4}" text-anchor="end" class="sankey-bar-count">{n}</text></g>'
flow+='''</svg></div><footer class="sankey-footnote"><span>ⓘ Each side is independent; incoming references do not prove an end-to-end runtime path.</span><span>Widths proportional to static relationships only</span></footer></section></main>'''
(D/'V4_FLOW_PREVIEW.html').write_text(page(header.format(map_active='',flow_active='active')+flow,'V4 Sankey lens'))
